const needsId = new Set<string>();
for (const [label, group] of byLabel) {
    if (
        group.some((entry) =>
            group.some(
                (other) =>
                    other.id !== entry.id &&
                    (other.connection === entry.connection ||
                        lastSegment(other.id) !== lastSegment(entry.id)),
            ),
        )
    ) {
        needsId.add(label);
    }
}
const shares: (id: string, connection?: string) => boolean = (id) =>
    needsId.has(nameOf(id));
const labelOf = (id: string, connection?: string): string =>
    shares(id, connection) ? `${nameOf(id)} (${id})` : nameOf(id);
